import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BlogPostActions } from '@/components/BlogPostActions'
import type { Comment, Post } from '@/types/blog'

export const revalidate = 300
export const dynamicParams = true

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

async function getPost(id: string): Promise<Post | null> {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}`,
    { next: { revalidate: 300 } }
  )

  if (!response.ok) {
    return null
  }

  const post = (await response.json()) as Post
  if (!post || !post.id) {
    return null
  }

  return post
}

async function getComments(id: string): Promise<Comment[]> {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  )

  if (!response.ok) {
    throw new Error('Failed to fetch comments')
  }

  return response.json() as Promise<Comment[]>
}

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const response = await fetch('https://jsonplaceholder.typicode.com/posts')

  if (!response.ok) {
    return []
  }

  const posts = (await response.json()) as Post[]

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return {
      title: 'Post Not Found',
    }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    notFound()
  }

  const comments = await getComments(id)

  return (
    <article>
      <BlogPostActions />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

import { NextResponse } from 'next/server'
import type { ApiError, ApiPost } from '@/types/blog'

interface CreatePostBody {
  title?: string
  content?: string
}

export async function GET(): Promise<NextResponse<ApiPost[]>> {
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts, { status: 200 })
}

export async function POST(
  request: Request
): Promise<NextResponse<ApiPost | ApiError>> {
  const body = (await request.json()) as CreatePostBody
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextResponse } from 'next/server'
import type { ApiPost, DeleteResult } from '@/types/blog'

interface RouteContext {
  params: Promise<{ id: string }>
}

interface UpdatePostBody {
  title?: string
  content?: string
}

export async function GET(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await context.params

  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: Request,
  context: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await context.params
  const body = (await request.json()) as UpdatePostBody
  const { title, content } = body

  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<DeleteResult>> {
  const { id } = await context.params

  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}
